function averages(r){return dmg.map((_,i)=>(r.shield[i]+r.armor[i]+r.hull[i])/3)}
function bestAmmo(r,family){
  const av=averages(r);
  return DB.ammo.filter(a=>a.family===family).map(a=>{
    const score=a.dmg.reduce((sum,v,i)=>sum+v*(1-av[i]/100),0);
    return {...a,score};
  }).sort((a,b)=>b.score-a.score || a.name.localeCompare(b.name)).slice(0,2);
}

function bestAmmo(r,family){
  const av=averages(r);
  return DB.ammo.filter(a=>a.family===family).map(a=>{
    const score=a.dmg.reduce((sum,v,i)=>sum+v*(1-av[i]/100),0);
    return {...a,score};
  }).sort((a,b)=>b.score-a.score || a.name.localeCompare(b.name)).slice(0,2);
}

function likelyFit(y){
  if(!y||!y.styles)return {fit:"Not available",engage:"Not available",range:8500,transversal:700};
  const styles=y.styles.split(" · ");
  const preferred=["Brawl","Scram kite","Web kite","Kite","Anti-kite","10MN kite","Polarized"];
  const fit=preferred.find(x=>styles.includes(x))||styles[0];
  const data={
    "Brawl":{engage:"Brawl · <5 km",range:3000,transversal:600},
    "Scram kite":{engage:"Scram kite · 5–10 km",range:8500,transversal:700},
    "Web kite":{engage:"Web kite · 10–13 km",range:11500,transversal:500},
    "Kite":{engage:"Kite · >20 km",range:24000,transversal:300},
    "Anti-kite":{engage:"Anti-kite · <5 km",range:4000,transversal:700},
    "10MN kite":{engage:"10MN kite · ~10–20 km",range:15000,transversal:350},
    "Polarized":{engage:"Polarized · close range",range:4000,transversal:700}
  }[fit]||{engage:"Depends on fit",range:8500,transversal:700};
  return {fit,engage:data.engage,range:data.range,transversal:data.transversal};
}

function threatFor(y){
  if(!y)return {label:"Unknown",cls:""};
  if(y.tier==="Top"||y.tier==="Balanced Plus")return {label:"High",cls:"threat-high"};
  if(y.tier==="Balanced")return {label:"Medium",cls:"threat-medium"};
  return {label:"Low",cls:"threat-low"};
}

function tacticalWeakness(s,y,av){
  const tank=(y&&y.tank||"").toLowerCase();
  let layer=null;
  if(tank.includes("shield") && !tank.includes("armor")) layer=s.res.shield;
  else if(tank.includes("armor")) layer=s.res.armor;
  else if(tank.includes("shield/armor")){
    const sm=s.res.shield.reduce((a,b)=>a+b,0)/4, am=s.res.armor.reduce((a,b)=>a+b,0)/4;
    layer=sm<=am?s.res.shield:s.res.armor;
  }
  const values=layer||av;
  const i=values.indexOf(Math.min(...values));
  return {type:layer?(tank.includes("armor")?"armor":"shield"):"average",name:dmg[i],values};
}

function baseAmmoName(name){
  return name.replace(/^(Republic Fleet|Domination|Arch Angel|Imperial Navy|Federation Navy|Caldari Navy)\s+/,"").trim();
}

function ammoApplicationProfile(a){
  const base=baseAmmoName(a.name);
  const profiles={
    "EMP S":{optimal:-0.50,tracking:0},"Fusion S":{optimal:-0.50,tracking:0},"Phased Plasma S":{optimal:-0.50,tracking:0},
    "Titanium Sabot S":{optimal:0,tracking:0.20},"Depleted Uranium S":{optimal:0,tracking:0.20},
    "Proton S":{optimal:0.60,tracking:0.05},"Nuclear S":{optimal:0.60,tracking:0.05},"Carbonized Lead S":{optimal:0.60,tracking:0.05},
    "Multifrequency S":{optimal:-0.50},"Gamma S":{optimal:-0.375},"Xray S":{optimal:-0.25},"Ultraviolet S":{optimal:-0.125},
    "Standard S":{optimal:0},"Infrared S":{optimal:0.20},"Microwave S":{optimal:0.40},"Radio S":{optimal:0.60},
    "Antimatter Charge S":{optimal:-0.50},"Plutonium Charge S":{optimal:-0.375},"Uranium Charge S":{optimal:-0.25},
    "Thorium Charge S":{optimal:-0.125},"Lead Charge S":{optimal:0},"Iridium Charge S":{optimal:0.125},
    "Tungsten Charge S":{optimal:0.25},"Iron Charge S":{optimal:0.60}
  };
  const p=profiles[base]||{};
  return {optimal:p.optimal??a.optimal??0,falloff:p.falloff??a.falloff??0,tracking:p.tracking??a.tracking??0};
}

function yearbookAmmoBias(a,w,fit){
  const base=baseAmmoName(a.name);
  let bias=0;
  if(w.type==="Artillery" && (fit.fit==="Kite"||fit.fit==="Web kite") && base==="Depleted Uranium S") bias+=0.04;
  if(w.type==="Beam" && fit.fit==="Kite" && base==="Xray S") bias+=0.04;
  if(w.type==="Beam" && fit.fit==="Scram kite" && base==="Xray S") bias+=0.02;
  if(w.type==="Pulse" && fit.fit==="Scram kite" && base==="Scorch S") bias-=0.05;
  if(w.type==="Pulse" && (fit.fit==="Brawl"||fit.fit==="Polarized") && base==="Conflagration S") bias+=0.04;
  return bias;
}

function turretApplication(w,a,fit){
  if(!w.tracking)return 1;
  const p=ammoApplicationProfile(a);
  const opt=w.optimal*(1+p.optimal);
  const fall=w.falloff*(1+p.falloff);
  const rangeFactor=fit.range<=opt?1:Math.pow(0.5,Math.pow((fit.range-opt)/Math.max(fall,1),2));
  const angular=fit.transversal/Math.max(fit.range,1);
  const effectiveTracking=(w.tracking/1000)*(1+p.tracking);
  const trackingTerm=angular/effectiveTracking;
  const trackingFactor=Math.pow(0.5,trackingTerm*trackingTerm);
  return Math.max(0,Math.min(1,rangeFactor*trackingFactor));
}

function ammoCandidates(values,w,fit){
  return DB.ammo
    .filter(a=>a.family===w.family && (!a.weaponTypes || a.weaponTypes.includes(w.type)))
    .map(a=>{
      const raw=a.dmg.reduce((sum,v,i)=>sum+v*(1-values[i]/100),0);
      const application=w.tracking?turretApplication(w,a,fit):1;
      // Balanced: 70% damage / 30% application. Yearbook priors are deliberately small.
      const balance=raw*(0.70+0.30*application)*(1+yearbookAmmoBias(a,w,fit));
      return {...a,rawScore:raw,application,balance};
    });
}

function bestAmmoProfiles(values,w,fit){
  const candidates=ammoCandidates(values,w,fit);
  const weaknessIndex=values.indexOf(Math.min(...values));
  const weaknessResistance=values[weaknessIndex];
  const weaknessName=dmg[weaknessIndex];

  // All three recommendations now exploit the target's calculated damage weakness.
  // "Best damage" maximises resistance-adjusted damage, with weakness damage as the tie-break.
  // "Best application" maximises damage that can actually be applied at the likely engagement
  // range/transversal, rather than selecting an ammo type on tracking/range alone.
  // "Best balance" keeps the existing 70/30 damage/application model, but adds a modest
  // explicit bonus when the ammo meaningfully concentrates damage into the weakest type.
  const scored=candidates.map(a=>{
    const weaknessRaw=a.dmg[weaknessIndex]||0;
    const weaknessDamage=weaknessRaw*(1-weaknessResistance/100);
    const appliedDamage=a.rawScore*a.application;

    return {
      ...a,
      weaknessName,
      weaknessResistance,
      weaknessRaw,
      weaknessDamage,
      appliedDamage
    };
  });

  const maxWeakness=Math.max(...scored.map(a=>a.weaknessDamage),0);
  const maxApplied=Math.max(...scored.map(a=>a.appliedDamage),0);

  scored.forEach(a=>{
    const weaknessShare=maxWeakness>0 ? a.weaknessDamage/maxWeakness : 0;
    const appliedShare=maxApplied>0 ? a.appliedDamage/maxApplied : 0;

    // Small weakness-aware lift: enough to change a marginal recommendation,
    // but not enough to override a clearly superior ammo choice.
    a.weaknessBonus=1 + (0.10*weaknessShare);
    a.applicationScore=a.appliedDamage*(0.80 + 0.20*weaknessShare);
    a.balanceScore=a.balance*a.weaknessBonus;
    a.appliedScore=a.appliedDamage;
  });

  const bestDamage=[...scored].sort(
    (a,b)=>b.rawScore-a.rawScore ||
           b.weaknessDamage-a.weaknessDamage ||
           b.application-a.application ||
           a.name.localeCompare(b.name)
  )[0];

  const bestApplication=[...scored].sort(
    (a,b)=>b.applicationScore-a.applicationScore ||
           b.appliedDamage-a.appliedDamage ||
           b.weaknessDamage-a.weaknessDamage ||
           a.name.localeCompare(b.name)
  )[0];

  const bestBalance=[...scored].sort(
    (a,b)=>b.balanceScore-a.balanceScore ||
           b.rawScore-a.rawScore ||
           b.weaknessDamage-a.weaknessDamage ||
           a.name.localeCompare(b.name)
  )[0];

  return {damage:bestDamage,application:bestApplication,balance:bestBalance};
}

function bestDroneForWeakness(weakness){
  const d=TACTICAL_DRONES.find(x=>x.damage===weakness);
  return d||TACTICAL_DRONES[0];
}

function droneRecommendation(wk){
  const d=bestDroneForWeakness(wk.name);
  return {name:d.name,damage:d.damage};
}

function yearbookWeakness(s,y){
  return y ? (YEARBOOK_WEAKNESSES[s.name] || "No specific weakness is stated in the Yearbook profile.") :
    "No Yearbook profile is available for this ship.";
}

