export const ships=DB.ships;
export const damageTypes=dmg;
export const weapons=TACTICAL_WEAPONS;
export const sdeBuild=DB.sdeBuild;
export function yearbook(ship){return YEARBOOK[ship.name]||null;}
export function shipImage(ship){return SHIP_IMAGES[ship.id];}
export function sortedShips(list){return [...list].sort((a,b)=>(YEARBOOK[b.name]?.engagements??-1)-(YEARBOOK[a.name]?.engagements??-1)||a.name.localeCompare(b.name));}
export function profile(ship,weaponLabel){
 const y=yearbook(ship),av=averages(ship.res),wk=tacticalWeakness(ship,y,av),fit=likelyFit(y);
 const weapon=weapons.find(w=>w.label===weaponLabel)||weapons[0];
 return {average:av,weakest:dmg[av.indexOf(Math.min(...av))],weakestResistance:Math.min(...av),weakness:wk,fit,threat:threatFor(y),ammo:bestAmmoProfiles(wk.values,weapon,fit),drone:droneRecommendation(wk),commentary:yearbookWeakness(ship,y),rankings:["Laser","Hybrid","Projectile","Light Missiles","Rockets","Advanced Light Missiles","Advanced Rockets"].map(family=>({family,ammo:bestAmmo(ship.res,family)}))};
}
